      out.write("<!-- ??????????????? CHAT FLOTANTE ??????????????? -->\n");
      out.write("<button id=\"chat-fab\" title=\"Chat interno SADU\" onclick=\"toggleChat()\">\n");
      out.write("    <span id=\"chat-fab-icon\">&#128172;</span>\n");
      out.write("    <span id=\"chat-badge\"></span>\n");
      out.write("</button>\n");
      out.write("\n");
      out.write("<div id=\"chat-panel\">\n");
      out.write("    <div id=\"chat-header\">\n");
      out.write("        <div>\n");
      out.write("            <span>&#128172; Chat interno</span>\n");
      out.write("            <small id=\"chat-subtitulo\">Cargando mensajes...</small>\n");
      out.write("        </div>\n");
      out.write("        <button id=\"btn-cerrar-chat\" onclick=\"toggleChat()\" title=\"Cerrar\">&#10005;</button>\n");
      out.write("    </div>\n");
      out.write("\n");
      out.write("    <div id=\"chat-mensajes\">\n");
      out.write("        <div class=\"chat-sin-mensajes\">Cargando...</div>\n");
      out.write("    </div>\n");
      out.write("\n");
      out.write("    <div id=\"chat-form\">\n");
      out.write("        <input  id=\"chat-asunto\" type=\"text\" placeholder=\"Asunto del mensaje...\" maxlength=\"120\">\n");
      out.write("        <div id=\"chat-fila-envio\">\n");
      out.write("            <textarea id=\"chat-texto\" placeholder=\"Escribe tu mensaje...\"></textarea>\n");
      out.write("            <button   id=\"btn-enviar-chat\" onclick=\"enviarMensaje()\" title=\"Enviar\">&#10148;</button>\n");
      out.write("        </div>\n");
      out.write("        <span id=\"chat-error\"></span>\n");
      out.write("    </div>\n");
      out.write("</div>\n");
      out.write("\n");
      out.write("<script>\n");
      out.write("// ??? Estado del chat ???????????????????????????????????????????\n");
      out.write("const ID_USUARIO_ACTUAL = ");
      out.print( idUserSidebar );
      out.write(";\n");
      out.write("let chatAbierto     = false;\n");
      out.write("let ultimoIdMensaje = 0;\n");
      out.write("let intervaloChat   = null;\n");
      out.write("\n");
      out.write("// ??? Abrir / cerrar panel ??????????????????????????????????????\n");
      out.write("function toggleChat() {\n");
      out.write("    chatAbierto = !chatAbierto;\n");
      out.write("    const panel = document.getElementById('chat-panel');\n");
      out.write("    const icon  = document.getElementById('chat-fab-icon');\n");
      out.write("    if (chatAbierto) {\n");
      out.write("        panel.classList.add('abierto');\n");
      out.write("        icon.innerHTML = '&#10005;';\n");
      out.write("        ocultarBadge();\n");
      out.write("        cargarMensajes();\n");
      out.write("        intervaloChat = setInterval(cargarMensajes, 8000);\n");
      out.write("    } else {\n");
      out.write("        panel.classList.remove('abierto');\n");
      out.write("        icon.innerHTML = '&#128172;';\n");
      out.write("        clearInterval(intervaloChat);\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("// ??? Cargar mensajes via fetch ??????????????????????????????????\n");
      out.write("function cargarMensajes() {\n");
      out.write("    fetch('ChatJsonServlet')\n");
      out.write("        .then(function(r) { return r.json(); })\n");
      out.write("        .then(function(datos) {\n");
      out.write("            var area = document.getElementById('chat-mensajes');\n");
      out.write("            var sub  = document.getElementById('chat-subtitulo');\n");
      out.write("\n");
      out.write("            if (!Array.isArray(datos) || datos.length === 0) {\n");
      out.write("                area.innerHTML = '<div class=\"chat-sin-mensajes\">&#128172; A&uacute;n no hay mensajes.<br>&#161;S&eacute; el primero en escribir!</div>';\n");
      out.write("                sub.textContent = '0 mensajes';\n");
      out.write("                return;\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            // Detectar mensajes nuevos para el badge\n");
      out.write("            var maxId = Math.max.apply(null, datos.map(function(m) { return m.idMensaje; }));\n");
      out.write("            if (!chatAbierto && maxId > ultimoIdMensaje && ultimoIdMensaje > 0) {\n");
      out.write("                mostrarBadge(datos.filter(function(m) { return m.idMensaje > ultimoIdMensaje; }).length);\n");
      out.write("            }\n");
      out.write("            ultimoIdMensaje = maxId;\n");
      out.write("\n");
      out.write("            sub.textContent = datos.length + ' mensaje' + (datos.length !== 1 ? 's' : '');\n");
      out.write("\n");
      out.write("            var estabaAbajo = area.scrollHeight - area.scrollTop - area.clientHeight < 40;\n");
      out.write("\n");
      out.write("            // Renderizar burbujas ? más recientes arriba (ya vienen DESC del servidor)\n");
      out.write("            var html = '';\n");
      out.write("            for (var j = datos.length - 1; j >= 0; j--) {\n");
      out.write("                var m      = datos[j];\n");
      out.write("                var propio = m.idUsuario === ID_USUARIO_ACTUAL;\n");
      out.write("                var clase  = propio ? 'propio' : 'ajeno';\n");
      out.write("                var hora   = m.fechaEnvio ? new Date(m.fechaEnvio).toLocaleTimeString('es-CO', {hour:'2-digit', minute:'2-digit'}) : '';\n");
      out.write("                var autor  = !propio ? '<div class=\"burbuja-autor\">' + esc(m.nombreUsuario) + '</div>' : '';\n");
      out.write("                html += '<div class=\"chat-burbuja ' + clase + '\">'\n");
      out.write("                      + autor\n");
      out.write("                      + '<div class=\"burbuja-asunto\">' + esc(m.asunto)  + '</div>'\n");
      out.write("                      + '<div class=\"burbuja-texto\">'  + esc(m.mensaje) + '</div>'\n");
      out.write("                      + '<div class=\"burbuja-hora\">'   + hora           + '</div>'\n");
      out.write("                      + '</div>';\n");
      out.write("            }\n");
      out.write("            area.innerHTML = html;\n");
      out.write("\n");
      out.write("            if (estabaAbajo) area.scrollTop = area.scrollHeight;\n");
      out.write("        })\n");
      out.write("        .catch(function() {\n");
      out.write("            document.getElementById('chat-subtitulo').textContent = 'Error al cargar';\n");
      out.write("        });\n");
      out.write("}\n");
      out.write("\n");
      out.write("// ??? Enviar mensaje (POST /EnviarMensajeServlet) ????????????????\n");
      out.write("function enviarMensaje() {\n");
      out.write("    var asunto  = document.getElementById('chat-asunto').value.trim();\n");
      out.write("    var mensaje = document.getElementById('chat-texto').value.trim();\n");
      out.write("    var errorEl = document.getElementById('chat-error');\n");
      out.write("    var btnEnv  = document.getElementById('btn-enviar-chat');\n");
      out.write("\n");
      out.write("    errorEl.style.display = 'none';\n");
      out.write("\n");
      out.write("    if (!asunto)  { mostrarError('Escribe un asunto antes de enviar.'); return; }\n");
      out.write("    if (!mensaje) { mostrarError('El mensaje no puede estar vac&iacute;o.'); return; }\n");
      out.write("\n");
      out.write("    btnEnv.disabled     = true;\n");
      out.write("    btnEnv.textContent  = '...';\n");
      out.write("\n");
      out.write("    var formData = new FormData();\n");
      out.write("    formData.append('asunto',  asunto);\n");
      out.write("    formData.append('mensaje', mensaje);\n");
      out.write("\n");
      out.write("    fetch('EnviarMensajeServlet', { method: 'POST', body: formData })\n");
      out.write("        .then(function() {\n");
      out.write("            document.getElementById('chat-asunto').value = '';\n");
      out.write("            document.getElementById('chat-texto').value  = '';\n");
      out.write("            cargarMensajes();\n");
      out.write("        })\n");
      out.write("        .catch(function() { mostrarError('No se pudo enviar. Intenta de nuevo.'); })\n");
      out.write("        .finally(function() {\n");
      out.write("            btnEnv.disabled    = false;\n");
      out.write("            btnEnv.innerHTML   = '&#10148;';\n");
      out.write("        });\n");
      out.write("}\n");
      out.write("\n");
      out.write("// Enviar con Enter (Shift+Enter = salto de línea)\n");
      out.write("document.getElementById('chat-texto').addEventListener('keydown', function(e) {\n");
      out.write("    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); enviarMensaje(); }\n");
      out.write("});\n");
      out.write("\n");
      out.write("// ??? Badge de mensajes nuevos ???????????????????????????????????\n");
      out.write("function mostrarBadge(n) {\n");
      out.write("    var b = document.getElementById('chat-badge');\n");
      out.write("    b.textContent   = n > 9 ? '9+' : n;\n");
      out.write("    b.style.display = 'flex';\n");
      out.write("}\n");
      out.write("function ocultarBadge() {\n");
      out.write("    document.getElementById('chat-badge').style.display = 'none';\n");
      out.write("}\n");
      out.write("function mostrarError(msg) {\n");
      out.write("    var e = document.getElementById('chat-error');\n");
      out.write("    e.innerHTML     = msg;\n");
      out.write("    e.style.display = 'block';\n");
      out.write("}\n");
      out.write("\n");
      out.write("// Polling silencioso en segundo plano (panel cerrado) cada 20 s\n");
      out.write("setInterval(function() {\n");
      out.write("    if (!chatAbierto) {\n");
      out.write("        fetch('ChatJsonServlet')\n");
      out.write("            .then(function(r) { return r.json(); })\n");
      out.write("            .then(function(datos) {\n");
      out.write("                if (!Array.isArray(datos) || datos.length === 0) return;\n");
      out.write("                var maxId = Math.max.apply(null, datos.map(function(m) { return m.idMensaje; }));\n");
      out.write("                if (ultimoIdMensaje === 0) { ultimoIdMensaje = maxId; return; }\n");
      out.write("                if (maxId > ultimoIdMensaje) {\n");
      out.write("                    mostrarBadge(datos.filter(function(m) { return m.idMensaje > ultimoIdMensaje; }).length);\n");
      out.write("                }\n");
      out.write("            }).catch(function() {});\n");
      out.write("    }\n");
      out.write("}, 20000);\n");
      out.write("\n");
      out.write("// Carga inicial silenciosa para obtener el ultimoIdMensaje base\n");
      out.write("fetch('ChatJsonServlet')\n");
      out.write("    .then(function(r) { return r.json(); })\n");
      out.write("    .then(function(datos) {\n");
      out.write("        if (Array.isArray(datos) && datos.length > 0)\n");
      out.write("            ultimoIdMensaje = Math.max.apply(null, datos.map(function(m) { return m.idMensaje; }));\n");
      out.write("    }).catch(function() {});\n");
      out.write("\n");
      out.write("// Utilidad ? escapar HTML para evitar XSS\n");
      out.write("function esc(str) {\n");
      out.write("    if (!str) return '';\n");
      out.write("    return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')\n");
      out.write("              .replace(/\"/g,'&quot;').replace(/'/g,'&#039;');\n");
      out.write("}\n");
      out.write("</script>\n");
